create or replace function public.perform_checkin(p_token text,p_cpf text,p_birth_date date) returns text language plpgsql security definer set search_path=public as $$ declare d uuid; p uuid; begin select id into d from event_days where checkin_open and token_hash=encode(digest(p_token,'sha256'),'hex'); if not found then return 'invalid_token'; end if; select id into p from participants where cpf=regexp_replace(p_cpf,'\D','','g') and birth_date=p_birth_date; if not found then return 'participant_not_found'; end if; insert into attendance(event_day_id,participant_id) values(d,p) on conflict(event_day_id,participant_id) do nothing; if found then return 'checked_in'; end if; return 'already_checked_in'; end; $$;
revoke all on function public.perform_checkin(text,text,date) from public;
